return ['domain'=>'dosieci-wp-doctor','plural-forms'=>'nplurals=3; plural=(n == 1) ? 0 : ((n % 10 >= 2 && n % 10 <= 4 && (n % 100 < 12 || n % 100 > 14)) ? 1 : 2);','language'=>'pl_PL','project-id-version'=>'DoSieci WP Doctor 1.0.0','pot-creation-date'=>'2026-09-24T18:15:40+00:00','po-revision-date'=>'2026-09-24T18:15:40+00:00','messages'=>['DoSieci WP Doctor'=>'DoSieci WP Doctor','https://dosieci.pl/wtyczki/wp-doctor/'=>'https://dosieci.pl/wtyczki/wp-doctor/','An explainable, read-only technical audit of WordPress and WooCommerce. It shows what is wrong and what to do about it, but never changes anything automatically.'=>'Wyjaśnialny audyt techniczny WordPressa i WooCommerce. Wyłącznie do odczytu — pokazuje, co jest nie tak i co z tym zrobić, ale niczego nie zmienia automatycznie.','DoSieci'=>'DoSieci','https://dosieci.pl/'=>'https://dosieci.pl/','PHP version'=>'Wersja PHP','PHP %s is a current release.'=>'PHP %s to aktualne wydanie.','PHP %1$s only receives security fixes, until %2$s.'=>'PHP %1$s otrzymuje już tylko poprawki bezpieczeństwa, do %2$s.','Plan the upgrade to a newer PHP version with your host before that date.'=>'Zaplanuj z hostingiem przejście na nowszą wersję PHP przed tą datą.','PHP %s is actively supported.'=>'PHP %s jest aktywnie wspierane.','PHP %s no longer receives security fixes.'=>'PHP %s nie otrzymuje już poprawek bezpieczeństwa.','Ask your host to move the site to a supported PHP version and test the site after the switch.'=>'Poproś hosting o przeniesienie witryny na wspieraną wersję PHP i sprawdź witrynę po zmianie.','HTTPS'=>'HTTPS','The site is served over HTTPS.'=>'Witryna działa po HTTPS.','The site does not use HTTPS.'=>'Witryna nie używa HTTPS.','Enable an SSL certificate (for example Let\'s Encrypt) and change the site address to https://.'=>'Włącz certyfikat SSL (np. Let\'s Encrypt) i przestaw adres witryny na https://.','Debug mode'=>'Tryb debugowania','WP_DEBUG_DISPLAY is on, so error messages can be shown to visitors.'=>'WP_DEBUG_DISPLAY jest włączone — komunikaty błędów mogą być widoczne dla odwiedzających.','Set WP_DEBUG_DISPLAY to false in wp-config.php. Log errors to a file, not to the screen.'=>'Ustaw WP_DEBUG_DISPLAY na false w wp-config.php. Błędy zapisuj w pliku, nie wyświetlaj na ekranie.','WP_DEBUG is on (without displaying errors on screen).'=>'WP_DEBUG jest włączone (bez wyświetlania błędów na ekranie).','On a production site it should usually be off.'=>'Na witrynie produkcyjnej zwykle powinno być wyłączone.','Debugging is off.'=>'Debugowanie jest wyłączone.','Search engine visibility'=>'Widoczność w wyszukiwarkach','The site asks search engines not to index it.'=>'Witryna prosi wyszukiwarki o nieindeksowanie.','Untick "Discourage search engines from indexing this site" in Settings > Reading, unless this is intentional (for example on a staging site).'=>'Odznacz „Proś wyszukiwarki o nieindeksowanie tej witryny” w Ustawienia → Czytanie, o ile nie jest to celowe (np. na witrynie testowej).','The site can be indexed.'=>'Witryna może być indeksowana.','Permalink structure'=>'Struktura bezpośrednich odnośników','Plain permalinks (?p=123) are in use.'=>'Używane są proste odnośniki (?p=123).','Switch to a structure based on the post name in Settings > Permalinks.'=>'Przełącz na strukturę opartą na nazwie wpisu w Ustawienia → Bezpośrednie odnośniki.','A readable permalink structure is in use.'=>'Używana jest czytelna struktura odnośników.','Autoloaded options'=>'Autoładowane opcje','%d KB of options is loaded on every request.'=>'Przy każdym żądaniu ładuje się %d KB opcji.','Find the largest autoloaded entries and turn autoload off where it is not needed. Unused plugins and abandoned transients are the usual cause.'=>'Znajdź największe wpisy autoload i wyłącz autoload tam, gdzie nie jest potrzebny. Zwykle winne są nieużywane wtyczki i porzucone transienty.','The recommended limit is about 800 KB. Review the largest entries.'=>'Zalecany limit to ok. 800 KB. Sprawdź największe wpisy.','%d KB, below the recommended threshold.'=>'%d KB — poniżej zalecanego progu.','Post revisions'=>'Rewizje wpisów','There are no posts to assess.'=>'Brak wpisów do oceny.','Revisions: %1$d, posts: %2$d (%3$.1f revisions per post on average).'=>'Rewizje: %1$d, wpisy: %2$d (średnio %3$.1f rewizji na wpis).','Consider limiting WP_POST_REVISIONS. Do not bulk-delete revisions without a backup: it cannot be undone.'=>'Rozważ ograniczenie WP_POST_REVISIONS. Nie usuwaj rewizji hurtowo bez kopii zapasowej — tego nie da się cofnąć.','Revisions: %1$d, posts: %2$d.'=>'Rewizje: %1$d, wpisy: %2$d.','Transients'=>'Transienty','The database holds %d transient.'=>'W bazie jest %d transient.' . "\0" . 'W bazie są %d transienty.' . "\0" . 'W bazie jest %d transientów.','A large number of transients usually means there is no persistent object cache. Consider Redis or Memcached rather than clearing them by hand.'=>'Duża liczba transientów zwykle oznacza brak trwałego cache obiektowego. Rozważ Redis lub Memcached zamiast ręcznego czyszczenia.','%d transient.'=>'%d transient.' . "\0" . '%d transienty.' . "\0" . '%d transientów.','PHP memory limit'=>'Limit pamięci PHP','The memory limit is %d MB.'=>'Limit pamięci wynosi %d MB.','WooCommerce needs at least 128 MB (often 256 MB).'=>'WooCommerce potrzebuje co najmniej 128 MB (często 256 MB).','The memory limit is sufficient.'=>'Limit pamięci jest wystarczający.','Scheduled tasks (cron)'=>'Zadania cron','%d scheduled task is more than an hour overdue.'=>'%d zaplanowane zadanie jest opóźnione o ponad godzinę.' . "\0" . '%d zaplanowane zadania są opóźnione o ponad godzinę.' . "\0" . '%d zaplanowanych zadań jest opóźnionych o ponad godzinę.','WP-Cron only runs when the site gets traffic. On a low-traffic site, set up a system cron job that calls wp-cron.php.'=>'WP-Cron uruchamia się tylko przy ruchu na witrynie. Przy małym ruchu skonfiguruj systemowy cron wywołujący wp-cron.php.','%d scheduled task, none overdue.'=>'%d zaplanowane zadanie, bez opóźnień.' . "\0" . '%d zaplanowane zadania, bez opóźnień.' . "\0" . '%d zaplanowanych zadań, bez opóźnień.','Inactive plugins'=>'Nieaktywne wtyczki','%d inactive plugin is still installed.'=>'%d nieaktywna wtyczka wciąż jest zainstalowana.' . "\0" . '%d nieaktywne wtyczki wciąż są zainstalowane.' . "\0" . '%d nieaktywnych wtyczek wciąż jest zainstalowanych.','Inactive plugins can still contain vulnerable code reachable from the web. Delete the ones you do not plan to use.'=>'Nieaktywne wtyczki nadal mogą zawierać podatny kod dostępny z sieci. Usuń te, których nie planujesz używać.','%d inactive plugin.'=>'%d nieaktywna wtyczka.' . "\0" . '%d nieaktywne wtyczki.' . "\0" . '%d nieaktywnych wtyczek.','WP Doctor'=>'WP Doctor','Run scan'=>'Uruchom skan','You do not have permission to access this page.'=>'Nie masz uprawnień do tej strony.','OK'=>'OK','Warning'=>'Uwaga','Critical'=>'Krytyczne','Info'=>'Info','OK: %1$d, warnings: %2$d, critical: %3$d'=>'OK: %1$d, ostrzeżenia: %2$d, krytyczne: %3$d','The score is only meant for comparing one scan with the next. A high score does not mean the site is secure: it is a summary, not a guarantee.'=>'Wynik służy wyłącznie do porównywania kolejnych skanów. Wysoki wynik nie oznacza, że witryna jest bezpieczna — to skrót, nie gwarancja.','This scan is read-only. The plugin never changes, deletes or optimizes anything automatically.'=>'Ten skan jest wyłącznie do odczytu. Wtyczka niczego nie zmienia, nie usuwa i nie optymalizuje automatycznie.','Status'=>'Status','Check'=>'Sprawdzenie','Result'=>'Wynik','Recommendation'=>'Zalecenie']];